/* Lomenti Call: bilingual client questions. Contract draft 03.11.2026; not legal advice. */
const FAQ_GROUPS=[["Цена и оплата","Cena un apmaksa",[["Сколько стоит сайт?","Cik maksā mājaslapa?","Базовый сайт Start стоит 50 € в месяц уже с НДС. За первый год это 600 € с НДС, разделённые на 12 платежей. Из них 480 € приходится на разработку и 120 € — на сопровождение. В сумму не входят домен, хостинг и дополнительные функции, которые мы согласуем отдельно.","Start mājaslapa maksā 50 € mēnesī, jau ar PVN. Pirmajā gadā kopā tie ir 600 € ar PVN, sadalīti 12 maksājumos. No tiem 480 € ir izstrāde un 120 € — atbalsts. Domēns, hostings un papildu funkcijas nav iekļautas; tās saskaņojam atsevišķi."],["Почему именно 50 € в месяц, а не разовая оплата за сайт?","Kāpēc tieši 50 € mēnesī, nevis vienreizējs maksājums par mājaslapu?","Потому что мы предлагаем не просто готовый сайт, а удобное долгосрочное сотрудничество. Вместо крупного платежа сразу вы платите 50 € в месяц с НДС: за первый год это 600 €, включая разработку и сопровождение. Если у вас поменяется номер телефона, логотип или текст, не придётся каждый раз искать нового специалиста и отдельно оплачивать каждую небольшую правку: в поддержку входят две небольшие правки контента ежемесячно. Вы просто пишете нам, и мы помогаем обновить сайт. При этом сайт не нужно создавать заново из-за обычных изменений. Если же вы захотите полностью поменять стиль, структуру или добавить новые функции, мы предложим вариант доработки и заранее согласуем стоимость — такие крупные изменения не входят в две небольшие правки.","Tāpēc, ka piedāvājam ne tikai gatavu mājaslapu, bet arī ērtu ilgtermiņa sadarbību. Lielas vienreizējas summas vietā maksājat 50 € mēnesī ar PVN: pirmajā gadā kopā 600 €, ieskaitot izstrādi un atbalstu. Ja mainās tālruņa numurs, logotips vai teksts, nav katru reizi jāmeklē cits speciālists un atsevišķi jāmaksā par katru nelielu labojumu: atbalstā ietilpst divi nelieli satura labojumi mēnesī. Jūs vienkārši uzrakstāt mums, un mēs palīdzam atjaunināt vietni. Parastu izmaiņu dēļ mājaslapa nav jāveido no jauna. Ja vēlaties pilnībā mainīt dizainu, struktūru vai pievienot jaunas funkcijas, piedāvāsim risinājumu un iepriekš saskaņosim cenu — šādas lielas izmaiņas neietilpst divos nelielajos labojumos."],["Что входит в 50 €?","Kas iekļauts 50 €?","За 50 € в месяц, уже с НДС, мы создаём сайт до пяти информационных страниц с адаптивным дизайном, согласованными формами и необходимыми языковыми версиями. В первый год также входят сопровождение и две небольшие правки контента ежемесячно. Домен и хостинг оплачиваются отдельно. Сначала согласуем список страниц, языки и формы, чтобы было понятно, что вы получаете.","Par 50 € mēnesī, jau ar PVN, izveidojam mājaslapu ar līdz piecām informatīvām lapām, adaptīvu dizainu, saskaņotām formām un nepieciešamajām valodu versijām. Pirmajā gadā iekļauts arī atbalsts un divi nelieli satura labojumi mēnesī. Domēns un hostings tiek apmaksāti atsevišķi. Vispirms saskaņosim lapas, valodas un formas, lai būtu skaidrs, ko saņemsiet."],["Сколько за первый год?","Cik jāmaksā pirmajā gadā?","За первый год — 600 € с НДС, то есть по 50 € в месяц. Отдельно оплачиваются только заранее согласованные дополнительные услуги, например домен или хостинг. Это фиксированная стоимость Start; домен и хостинг выбираете и оплачиваете отдельно.","Pirmajā gadā — 600 € ar PVN jeb 50 € mēnesī. Atsevišķi maksā tikai par iepriekš saskaņotiem papildu pakalpojumiem, piemēram, domēnu vai hostingu. Tā ir fiksēta Start cena; domēnu un hostingu izvēlaties un apmaksājat atsevišķi."],["Есть первый взнос?","Vai ir pirmā iemaksa?","50 € после договора, до начала работ; входит в общую сумму. Это не дополнительная комиссия: платёж засчитывается как первый из двенадцати.","50 € pēc līguma, pirms darbu sākuma; iekļauti kopējā cenā. Tā nav papildu maksa: iemaksa ir pirmais no divpadsmit maksājumiem."],["Когда первый платёж?","Kad jāveic pirmais maksājums?","Для Start первый платёж — 50 € после согласования и подписания договора, но до начала разработки. Это не отдельный вступительный взнос: он входит в 600 € за первые 12 месяцев. Мы выставим счёт с реквизитами, чтобы вам было понятно, за что вы платите и когда начинается работа.","Start pirmais maksājums ir 50 € pēc līguma saskaņošanas un parakstīšanas, bet pirms izstrādes sākuma. Tā nav atsevišķa iestāšanās maksa: tā ietilpst 600 € par pirmajiem 12 mēnešiem. Nosūtīsim rēķinu ar rekvizītiem, lai būtu skaidrs, par ko maksājat un kad sākas darbs."],["Можно оплатить сразу?","Vai var samaksāt uzreiz?","Стандартно 12 платежей; единовременную оплату согласует команда. Если вам удобнее один платёж, передадим запрос команде и подтвердим условия письменно.","Standartā 12 maksājumi; vienreizēju apmaksu saskaņo komanda. Ja ērtāks viens maksājums, nodosim pieprasījumu komandai un rakstiski apstiprināsim nosacījumus."],["Можно банковским переводом?","Vai var maksāt ar pārskaitījumu?","Выставляем счета с реквизитами; способ оплаты подтвердим до договора. В счёте будут указаны сумма, назначение платежа и реквизиты получателя.","Izrakstām rēķinus ar rekvizītiem; maksāšanas veidu precizēsim pirms līguma. Rēķinā būs summa, maksājuma mērķis un saņēmēja rekvizīti."],["Есть официальные счета?","Vai izrakstāt rēķinus?","Да, платежи по сотрудничеству оформляем счетами в согласованном порядке. Для тарифа Start базовая сумма — 50 € в месяц с НДС, а за первый год — 600 €; отдельно могут быть только согласованные дополнительные услуги и расходы. Счёт содержит реквизиты и назначение платежа, чтобы вашей бухгалтерии было понятно, за что идёт оплата.","Jā, sadarbības maksājumus noformējam ar rēķiniem saskaņotajā kārtībā. Start pamatmaksa ir 50 € mēnesī ar PVN, pirmajā gadā kopā 600 €; atsevišķi ir tikai saskaņoti papildu darbi un izdevumi. Rēķinā ir rekvizīti un maksājuma mērķis, lai grāmatvedībai būtu skaidrs, par ko tiek maksāts."],["Цена с НДС?","Vai cenā iekļauts PVN?","Да, конечно. Указанные 50 € в месяц — это уже окончательная цена с НДС. Дополнительно НДС к этой сумме не прибавляется. То есть к объявленным 50 € ничего сверху за НДС не добавляется.","Jā. Norādītie 50 € mēnesī jau ir gala cena ar PVN. Papildu PVN šai summai netiek pieskaitīts. Tātad norādītajiem 50 € PVN papildus netiek pieskaitīts."],["Есть скрытые платежи?","Vai ir slēptas izmaksas?","Нет, дополнительные работы мы не начинаем без вашего письменного согласия. Сразу уточним только один момент: домен, хостинг и сторонние сервисы оплачиваются отдельно, поэтому их стоимость обсудим заранее. Любую новую функцию или работу сначала оценим и только потом попросим подтверждение.","Nē, papildu darbus neveicam bez jūsu rakstiskas piekrišanas. Vienīgi domēns, hostings un trešo pušu pakalpojumi tiek apmaksāti atsevišķi, tādēļ to izmaksas izrunāsim iepriekš. Jebkuru jaunu funkciju vai darbu vispirms novērtēsim un tikai tad lūgsim apstiprinājumu."],["Сколько стоят домен и хостинг?","Cik maksā domēns un hostings?","Обычно для небольшого сайта можно ориентироваться на хостинг примерно от 3–5 € в месяц, а более функциональные варианты могут стоить 5–10 € и выше. Это примерный ориентир, не фиксированный тариф: точную цену подберём вместе с вами у провайдера. Домен оплачивается отдельно, и оба аккаунта будут оформлены на вас. Точная сумма зависит от выбранного поставщика, объёма ресурсов и срока оплаты.","Nelielai mājaslapai orientējoša hostinga cena var sākties aptuveni no 3–5 € mēnesī, savukārt plašāki risinājumi var maksāt 5–10 € vai vairāk. Tā ir aptuvena norāde, nevis fiksēta cena: precīzu piedāvājumu palīdzēsim izvēlēties pie pakalpojumu sniedzēja. Domēns tiek apmaksāts atsevišķi, un abi konti būs uz jūsu vārda. Precīza summa atkarīga no pakalpojumu sniedzēja, resursiem un apmaksas perioda."],["Сколько стоит несколько языков?","Cik maksā vairākas valodas?","Языковые версии уже входят в стоимость сайта Start. Мы заранее уточним, какие языки вам нужны, чтобы правильно подготовить структуру и содержание. Если потребуется профессиональный перевод текстов или нестандартная функциональность, это отдельно обсудим до начала работ. Нужные языки укажем в задании; отдельно уточним, кто предоставляет готовые переводы.","Start mājaslapas cenā jau ir iekļautas valodu versijas. Iepriekš precizēsim, kuras valodas jums nepieciešamas, lai pareizi sagatavotu struktūru un saturu. Ja būs vajadzīgs profesionāls tekstu tulkojums vai nestandarta funkcijas, to atsevišķi apspriedīsim pirms darbu sākuma. Nepieciešamās valodas norādīsim uzdevumā; atsevišķi precizēsim, kurš sagādā tulkojumus."],["Цена дополнительных страниц?","Cik maksā papildu lapas?","Конечно, мы всегда рады помочь, если вашему бизнесу нужно больше пяти страниц. Расскажите, что именно вы хотели бы добавить, и мы вместе найдём удобное решение — расширим сайт или предложим альтернативную структуру. Дополнительный объём и стоимость обязательно согласуем с вами заранее. Мы можем предложить объединить похожие разделы или расширить сайт, если это удобнее посетителям.","Ja jūsu uzņēmumam vajadzīgas vairāk nekā piecas lapas. Pastāstiet, ko vēlaties pievienot, un kopā atradīsim piemērotāko risinājumu — paplašināsim vietni vai piedāvāsim citu struktūru. Papildu darbu apjomu un cenu vienmēr saskaņosim iepriekš. Varam piedāvāt apvienot līdzīgas sadaļas vai paplašināt vietni, ja tā apmeklētājiem būs ērtāk."],["Что при просрочке платежа?","Kas notiek, ja maksājums kavējas?","После 14 дней просрочки и письменного предупреждения возможна приостановка работ и поддержки; ваш хостинг не отключаем. Если возникнут сложности с оплатой, лучше сообщить заранее — обсудим возможный порядок действий.","Pēc 14 dienu kavējuma un rakstiska brīdinājuma darbus un atbalstu var apturēt; jūsu hostingu neatslēdzam. Ja rodas maksājuma grūtības, labāk paziņot iepriekš — apspriedīsim iespējamo risinājumu."],["Могут ли цены измениться?","Vai cena var mainīties?","Нет, согласованная цена тарифа Start в течение первого года не меняется — всё строго по договору. Конечно, со временем у бизнеса могут появиться новые задачи. Мы заранее обсудим любые изменения и, если потребуется, предложим дополнительные услуги только с вашего согласия. Никаких неожиданных доплат. Изменение объёма работ не означает автоматического изменения базовой цены.","Nē, Start tarifa saskaņotā cena pirmā gada laikā nemainās — viss notiek stingri saskaņā ar līgumu. Protams, uzņēmumam laika gaitā var rasties jaunas vajadzības. Jebkuras izmaiņas apspriedīsim iepriekš un papildu pakalpojumus piedāvāsim tikai ar jūsu piekrišanu. Nekādu negaidītu piemaksu. Darbu apjoma maiņa nenozīmē automātisku pamatcenas maiņu."],["Сколько поддержка после года?","Cik maksā atbalsts pēc gada?","После первого года сопровождение стоит 50 € в месяц, уже с НДС, пока действует договор поддержки. Если поддержка больше не нужна, после первого года её можно прекратить с письменным предупреждением за 30 дней.","Pēc pirmā gada atbalsts maksā 50 € mēnesī, jau ar PVN, kamēr ir spēkā atbalsta līgums. Ja atbalsts vairs nav vajadzīgs, pēc pirmā gada to var izbeigt ar rakstisku 30 dienu brīdinājumu."],["Почему после года тоже 50 €?","Kāpēc pēc gada arī 50 €?","После первого года разработка уже оплачена, а 50 € в месяц относятся к дальнейшему сопровождению по договору. Если ваш бизнес развивается и сайту понадобится больше внимания, мы можем отдельно предложить расширенную поддержку: команда возьмёт на себя согласованный дополнительный объём работ за отдельную плату. Всё заранее обсудим, чтобы вы понимали, за что платите. Базовый объём поддержки остаётся тем, что согласован в договоре; новые задачи оцениваются отдельно.","Pēc pirmā gada izstrāde jau ir apmaksāta, bet 50 € mēnesī attiecas uz turpmāko atbalstu saskaņā ar līgumu. Ja jūsu uzņēmums attīstās un vietnei nepieciešama plašāka aprūpe, varam atsevišķi piedāvāt paplašinātu atbalstu: komanda uzņemsies saskaņotus papildu darbus par atsevišķu samaksu. Visu iepriekš izrunāsim, lai izmaksas būtu skaidras. Atbalsta pamatapjoms paliek līgumā saskaņotais; jaunus uzdevumus vērtē atsevišķi."],["Можно без поддержки?","Vai var bez atbalsta?","Другой вариант сотрудничества обсуждается индивидуально. Если нужен другой формат, сначала уточним, кто будет обновлять сайт и отвечать за техническую часть.","Citu sadarbības modeli apspriežam individuāli. Ja vajadzīgs cits modelis, vispirms precizēsim, kurš atjauninās vietni un atbildēs par tehnisko daļu."],["Скидка за несколько сайтов?","Vai ir atlaide vairākām vietnēm?","У нас прозрачная стоимость и понятные условия, поэтому мы не обещаем скидку автоматически. Мы можем создать сайт, помочь с настройкой домена и подобрать подходящий формат работы. Если у вас несколько проектов или вы планируете регулярно развивать сайты, давайте обсудим долгосрочное сотрудничество: так проще выстроить удобный процесс обновлений и подобрать решение под ваши задачи. Для нескольких проектов можем обсудить общий план работ, сроки и сопровождение, не обещая несогласованных скидок.","Mums ir skaidras cenas un sadarbības nosacījumi, tāpēc automātisku atlaidi nesolām. Varam izveidot vietni, palīdzēt iestatīt domēnu un izvēlēties piemērotu sadarbības veidu. Ja jums ir vairāki projekti vai plānojat regulāri attīstīt vietnes, apspriedīsim ilgtermiņa sadarbību — tā var ērtāk organizēt atjauninājumus un atrast jūsu vajadzībām atbilstošu risinājumu. Vairākiem projektiem varam apspriest kopīgu darbu plānu, termiņus un atbalstu, nesolot nesaskaņotas atlaides."]]],["Возможности сайта","Mājaslapas iespējas",[["Как будет выглядеть сайт?","Kā izskatīsies vietne?","Дизайн согласуем под компанию, покажем первый вариант. Сначала узнаем, какие услуги вы предлагаете и какой стиль вам близок, затем согласуем направление дизайна.","Dizainu saskaņosim ar uzņēmumu, parādīsim pirmo variantu. Vispirms noskaidrosim jūsu pakalpojumus un vēlamo stilu, tad saskaņosim dizaina virzienu."],["Есть примеры работ?","Vai ir darbu piemēri?","Да, покажем проекты и концепты, отдельно обозначив демонстрационные. Покажем, какие решения демонстрационные, а какие реализованы для заказчиков.","Jā, parādīsim projektus un konceptus, skaidri norādot demonstrācijas. Skaidri parādīsim, kuri risinājumi ir demonstrācijas un kuri īstenoti klientiem."],["Сайт уникальный или шаблон?","Vai vietne būs unikāla vai veidne?","Дизайн согласуется индивидуально; общие технические компоненты могут использоваться повторно. Внешний вид и содержание подбираются под ваш бизнес, а не копируются с чужого сайта.","Dizainu saskaņo individuāli; kopīgus tehniskos komponentus var izmantot atkārtoti. Izskatu un saturu pielāgojam jūsu uzņēmumam, nevis kopējam no citas vietnes."],["Какие пять страниц?","Kuras piecas lapas?","Например, главная, услуги, о нас, работы, контакты; точный список согласуем. Например, если важнее каталог услуг, можем изменить набор страниц до утверждения задания.","Piemēram, sākums, pakalpojumi, par mums, darbi, kontakti; precīzu sarakstu saskaņosim. Piemēram, ja svarīgāks pakalpojumu katalogs, lapu sastāvu varam mainīt pirms uzdevuma apstiprināšanas."],["Можно свою структуру?","Vai var izvēlēties struktūru?","Да, в пределах согласованного задания. Поможем определить, какую информацию клиент должен увидеть первой и как быстро найти контакты.","Jā, saskaņotā darba uzdevuma ietvaros. Palīdzēsim noteikt, ko apmeklētājam redzēt vispirms un kā ātri atrast kontaktus."],["Будет работать на телефоне?","Vai darbosies telefonā?","Да, обязательно. В тариф Start входит адаптивный дизайн, поэтому сайт будет подстраиваться под экран телефона, планшета и компьютера. Отдельно проверим удобство чтения, навигации и отправки заявок на небольшом экране.","Jā, noteikti. Start tarifā ir iekļauts adaptīvs dizains, tāpēc vietne pielāgosies telefonam, planšetei un datoram. Atsevišķi pārbaudīsim lasāmību, navigāciju un pieteikumu nosūtīšanu mazā ekrānā."],["Можно форму обратной связи?","Vai var pievienot saziņas formu?","Да, согласованная простая форма обратной связи может входить в Start. До разработки решим, какие поля действительно нужны — например, имя, email и сообщение — и на какой адрес должны приходить заявки. Если нужна онлайн-запись, личный кабинет или сложная интеграция, это отдельная задача с предварительной оценкой.","Jā, saskaņota vienkārša saziņas forma var ietilpt Start. Pirms izstrādes vienosimies, kuri lauki tiešām vajadzīgi, piemēram, vārds, e-pasts un ziņa, un uz kuru adresi nosūtīt pieteikumus. Ja vajadzīgs tiešsaistes pieraksts, lietotāja konts vai sarežģīta integrācija, tas ir atsevišķs uzdevums ar iepriekšēju novērtējumu."],["Фото, видео и галерея?","Foto, video un galerija?","Возможность и объём согласуем в задании. Важно заранее определить количество материалов и кто предоставит права на их использование.","Iespējas un apjomu saskaņosim uzdevumā. Svarīgi iepriekš noteikt materiālu daudzumu un to izmantošanas tiesības."],["Можно прайс-лист?","Vai var ievietot cenrādi?","Да, формат согласуем при подготовке содержания. Прайс можно разместить на отдельной странице или внутри раздела услуг — как удобнее вашим клиентам.","Jā, formātu saskaņosim, gatavojot saturu. Cenrādi var ievietot atsevišķā lapā vai pakalpojumu sadaļā — kā ērtāk klientiem."],["Каталог без онлайн-оплаты?","Katalogs bez tiešsaistes apmaksas?","Можем оценить отдельно; сложный каталог не включён автоматически в Start. Уточним количество позиций, фильтры и необходимость частого обновления информации.","Varam izvērtēt atsevišķi; sarežģīts katalogs nav automātiski iekļauts Start. Precizēsim pozīciju skaitu, filtrus un to, cik bieži informācija būs jāatjaunina."],["Можно онлайн-запись?","Vai var pievienot pierakstu?","Оценим интеграцию и стоимость отдельно. Нужно понять, хотите ли вы просто принимать запросы или синхронизировать свободное время с календарём.","Integrāciju un cenu izvērtēsim atsevišķi. Jāsaprot, vai vēlaties tikai saņemt pieprasījumus vai sinhronizēt brīvos laikus ar kalendāru."],["Можно WhatsApp и мессенджеры?","Vai var pievienot WhatsApp?","Ссылки и интеграции возможны по согласованию; автоматизация оценивается отдельно. Обычная кнопка связи и полноценная автоматическая интеграция — разные по объёму задачи.","Saites un integrācijas var saskaņot; automatizāciju vērtē atsevišķi. Parasta saziņas poga un pilna automātiska integrācija ir atšķirīga apjoma darbi."],["Несколько языков?","Vairākas valodas?","Да, конечно. Языковые версии входят в стоимость Start. Просто уточним, какие языки вам нужны и кто предоставляет готовые тексты, чтобы сайт был удобен для ваших клиентов. До начала работ согласуем перечень языков и наличие текстов для каждой версии.","Jā. Valodu versijas ir iekļautas Start cenā. Tikai precizēsim, kuras valodas jums vajadzīgas un kurš sagatavo tekstus, lai vietne būtu ērta jūsu klientiem. Pirms darbu sākuma saskaņosim valodas un tekstu pieejamību katrai versijai."],["Кто готовит тексты и фото?","Kas sagatavo tekstus un foto?","Ответственность указывается в приложении; обычно нужны материалы клиента. Если материалов пока нет, можем обсудить помощь с подготовкой, но не будем обещать её бесплатно без согласования.","Atbildību norāda pielikumā; parasti vajadzīgi klienta materiāli. Ja materiālu vēl nav, varam apspriest palīdzību sagatavošanā, bet nesolīsim to bez maksas bez vienošanās."],["Можно менять информацию самому?","Vai var pašam mainīt saturu?","Зависит от системы; панель управления согласуется отдельно. Если вам важно часто менять цены или товары, скажите об этом заранее — подберём подходящий способ управления.","Atkarīgs no sistēmas; administrēšanas paneli saskaņo atsevišķi. Ja bieži jāmaina cenas vai preces, pastāstiet iepriekš — izvēlēsimies piemērotu pārvaldības veidu."],["Можно подключить аналитику?","Vai var pievienot analītiku?","Обсудим сервис, настройку и требования к данным. Например, можно обсуждать статистику посещений и отправленных форм; выбор сервиса влияет на настройки конфиденциальности.","Apspriedīsim rīku, uzstādīšanu un datu prasības. Piemēram, var skatīt apmeklējumus un nosūtītās formas; rīka izvēle ietekmē privātuma iestatījumus."],["Будет в Google?","Vai vietne būs Google?","Индексацию и позиции гарантировать нельзя; технические меры обсудим. Мы можем обсудить техническую подготовку сайта к поиску, но позиция в выдаче зависит не только от разработки.","Indeksēšanu un pozīcijas garantēt nevar; tehniskos pasākumus apspriedīsim. Varam apspriest vietnes tehnisko sagatavošanu meklētājiem, bet pozīcija nav atkarīga tikai no izstrādes."],["Делаете SEO?","Vai piedāvājat SEO?","SEO-работы согласуются отдельно, Start не гарантирует продвижение. Если продвижение важно, определим конкретные работы и отдельный бюджет до их начала.","SEO darbus saskaņo atsevišķi; Start negarantē virzīšanu meklētājos. Ja meklētāju optimizācija ir svarīga, pirms sākuma noteiksim konkrētus darbus un budžetu."],["Гарантируете новых клиентов?","Vai garantējat jaunus klientus?","Мы не хотим обещать вам цифры, на которые нельзя честно повлиять. Хороший сайт может помочь клиентам найти информацию и связаться с вами, но конкретное количество заявок или продаж мы не гарантируем. Наша задача — сделать понятный и удобный инструмент для связи с вами, а не обещать заранее число продаж.","Nevēlamies solīt rezultātus, kurus nevaram godīgi garantēt. Laba vietne var palīdzēt klientiem atrast informāciju un sazināties ar jums, taču konkrētu pieteikumu vai pārdošanas skaitu negarantējam. Mūsu uzdevums ir radīt saprotamu saziņas rīku, nevis iepriekš solīt pārdošanas apjomu."],["Можно расширить до магазина?","Vai var vēlāk izveidot veikalu?","Да, как отдельный проект после оценки. При расширении оценим каталог, корзину, оплату, доставку и сохранность существующего содержания.","Jā, kā atsevišķu projektu pēc izvērtēšanas. Paplašinot izvērtēsim katalogu, grozu, apmaksu, piegādi un esošā satura saglabāšanu."]]],["Сроки и процесс","Termiņi un process",[["За сколько дней сделаете?","Cik dienās izstrādāsiet?","Срок укажем в приложении после оценки объёма и материалов. На сроки влияют число страниц, готовность материалов, согласования и дополнительные функции.","Termiņu norādīsim pielikumā pēc apjoma un materiālu izvērtēšanas. Termiņu ietekmē lapu skaits, materiālu gatavība, saskaņojumi un papildu funkcijas."],["Когда начнёте?","Kad sāksiet?","После договора, первого платежа и получения материалов; дату уточним. Чтобы не терять время, заранее соберём всё необходимое и определим порядок согласований.","Pēc līguma, pirmā maksājuma un materiālu saņemšanas; datumu precizēsim. Lai netērētu laiku, iepriekš savāksim vajadzīgo un vienosimies par saskaņošanas kārtību."],["Что нужно от меня?","Kas jums vajadzīgs no manis?","Задание, тексты, изображения, доступы и согласования. Если чего-то не хватает, составим конкретный список, чтобы вам не приходилось угадывать.","Uzdevums, teksti, attēli, piekļuves un saskaņojumi. Ja kaut kā trūkst, sagatavosim konkrētu sarakstu, lai jums nebūtu jāmin."],["Кто делает проект?","Kas izstrādās projektu?","Команда Lomenti; ответственное лицо укажем в документах. Вы будете знать, кому направлять материалы, замечания и вопросы по проекту.","Lomenti komanda; atbildīgo personu norādīsim dokumentos. Jūs zināsiet, kam sūtīt materiālus, piezīmes un jautājumus par projektu."],["Можно срочно?","Vai var steidzami?","Проверим возможность, срок и стоимость отдельно. Ускорение возможно не всегда, поэтому подтвердим реальный график до обещания даты.","Atsevišķi pārbaudīsim iespēju, termiņu un cenu. Paātrināšana ne vienmēr ir iespējama, tāpēc reālu grafiku apstiprināsim pirms datuma solīšanas."],["Когда первый дизайн?","Kad būs pirmais dizains?","Точную дату согласуем в плане проекта после утверждения задания и получения необходимых материалов. До первого показа определим набор страниц, содержание, фирменные цвета и примеры стиля, который вам подходит. Мы не называем произвольный срок до того, как увидим объём работ, чтобы потом не переносить обещанную дату.","Precīzu datumu saskaņosim projekta plānā pēc uzdevuma apstiprināšanas un vajadzīgo materiālu saņemšanas. Pirms pirmās demonstrācijas noteiksim lapu sarakstu, saturu, uzņēmuma krāsas un vēlamā stila piemērus. Nesolām patvaļīgu termiņu, pirms neesam redzējuši darbu apjomu."],["Можно следить за процессом?","Vai var sekot procesam?","Да, заранее согласуем, как вы будете видеть промежуточный результат: например, ссылкой на тестовую версию или сообщениями с изменениями. Важно определить, кто со стороны клиента даёт обратную связь, чтобы не получать противоречивые замечания. Частоту обновлений и контрольные точки зафиксируем в рабочем плане проекта.","Jā, iepriekš saskaņosim, kā redzēsiet starprezultātu, piemēram, ar saiti uz testa versiju vai ziņām par izmaiņām. Svarīgi noteikt klienta pārstāvi, kurš sniedz atsauksmes, lai nesaņemtu pretrunīgus komentārus. Informēšanas biežumu un pārbaudes punktus ierakstīsim projekta plānā."],["Если не понравится дизайн?","Ja dizains nepatiks?","После первого варианта предусмотрен раунд изменений. Лучше собрать замечания одним списком — так проще ничего не упустить и быстрее внести правки.","Pēc pirmā varianta paredzēta labojumu kārta. Labāk apkopot piezīmes vienā sarakstā — tā vieglāk neko nepalaist garām un ātrāk veikt labojumus."],["Сколько раундов изменений?","Cik labojumu kārtu?","В проекте предусмотрены два раунда согласованных исправлений дизайна и содержания. Раунд — это один собранный список замечаний, а не только одна поправка. Например, можно разом указать, что нужно поменять заголовок, фотографию и порядок блоков. Новый функционал и изменение утверждённого задания оцениваются отдельно.","Projektā paredzētas divas saskaņotu dizaina un satura labojumu kārtas. Viena kārta ir apkopots piezīmju saraksts, nevis tikai viena izmaiņa. Piemēram, vienlaikus var norādīt virsraksta, foto un bloku secības maiņu. Jaunas funkcijas un apstiprinātā uzdevuma maiņu vērtē atsevišķi."],["Если задержу материалы?","Ja kavēšu materiālus?","Срок может продлиться, об этом сообщим письменно. Когда материалы будут готовы, обновим план; задержка клиента не превращается в нарушение срока исполнителем.","Termiņš var pagarināties; par to informēsim rakstiski. Kad materiāli būs gatavi, atjaunosim plānu; klienta kavējums nav izpildītāja termiņa pārkāpums."],["Если вы опоздаете?","Ja jūs kavēsiet termiņu?","Разберём причину и дальнейшие действия; автоматический штраф не обещаем. Если возникнет задержка с нашей стороны, сообщим о ней и предложим дальнейший план письменно.","Izvērtēsim iemeslu un tālāko rīcību; automātisku līgumsodu nesolām. Ja kavējums būs mūsu pusē, par to paziņosim un rakstiski piedāvāsim turpmāko plānu."],["Как проходит приёмка?","Kā notiek pieņemšana?","7 рабочих дней на проверку и замечания; затем процедура напоминания. Проверяете согласованные функции и сообщаете конкретные замечания; скрытые недостатки этим сроком не отменяются.","7 darbdienas pārbaudei un piezīmēm; pēc tam atgādinājuma kārtība. Pārbaudāt saskaņotās funkcijas un sniedzat konkrētas piezīmes; slēptie trūkumi ar šo termiņu netiek izslēgti."],["Можно запускать поэтапно?","Vai var palaist pa posmiem?","Да, если до начала работ согласуем, что войдёт в каждый этап и как будем принимать результат. Например, сначала можно подготовить главную страницу и услуги, затем раздел работ и контакты. Количество страниц в Start — до пяти; сроки и объём этапов фиксируем в задании, а дополнительные функции оцениваем отдельно.","Jā, ja pirms darba sākuma saskaņojam katra posma saturu un pieņemšanas kārtību. Piemēram, vispirms var sagatavot sākumlapu un pakalpojumus, pēc tam darbu sadaļu un kontaktus. Start ietver līdz piecām lapām; posmu termiņus un apjomu ierakstām uzdevumā, bet papildu funkcijas novērtējam atsevišķi."]]],["Договор и гарантии","Līgums un garantijas",[["Будет договор?","Vai būs līgums?","Да, с приложением о работах, сроках и цене. В нём фиксируем не только цену, но и объём работ, порядок оплаты, приёмки и поддержки.","Jā, ar pielikumu par darbiem, termiņiem un cenu. Tajā fiksējam ne tikai cenu, bet arī darbu apjomu, apmaksas, pieņemšanas un atbalsta kārtību."],["Кто юридический исполнитель?","Kas juridiski sniedz pakalpojumu?","Актуальные реквизиты будут в договоре; уточним перед подписанием. Перед подписанием вы увидите точные данные стороны, с которой заключаете договор.","Aktuālie rekvizīti būs līgumā; precizēsim pirms parakstīšanas. Pirms parakstīšanas redzēsiet precīzus tās puses datus, ar kuru slēdzat līgumu."],["Вы зарегистрированы в Латвии?","Vai esat reģistrēti Latvijā?","Предоставим подтверждённые регистрационные данные перед договором. Проверяемые реквизиты предоставим до оплаты; не просим полагаться только на устное обещание.","Pirms līguma sniegsim apstiprinātus reģistrācijas datus. Pārbaudāmus rekvizītus sniegsim pirms apmaksas; nelūdzam paļauties tikai uz mutisku solījumu."],["Можно договор до оплаты?","Vai var saņemt līgumu pirms maksājuma?","Да, сначала согласуем и предоставим договор, а уже затем выставим первый счёт. В нём будут определены объём работ, платежи, правки, порядок приёмки и права на сайт. Вы сможете спокойно прочитать документ и задать вопросы до оплаты; начинать работу без согласованных условий не будем.","Jā, vispirms saskaņosim un nosūtīsim līgumu, pēc tam izrakstīsim pirmo rēķinu. Tajā būs noteikts darbu apjoms, maksājumi, labojumi, pieņemšanas kārtība un tiesības uz vietni. Varēsiet mierīgi izlasīt dokumentu un uzdot jautājumus pirms maksājuma; bez saskaņotiem nosacījumiem darbu nesāksim."],["На каком языке договор?","Kādā valodā ir līgums?","Основной текст на латышском, русский перевод информационный. Если понадобится пояснение на русском, поможем разобраться, но юридически важна согласованная латышская редакция.","Pamatteksts latviešu valodā, tulkojums krieviski informatīvs. Ja vajadzīgs skaidrojums krieviski, palīdzēsim, bet juridiski svarīga ir saskaņotā latviešu redakcija."],["Если результат не устроит?","Ja rezultāts neapmierinās?","Вы сможете проверить готовый сайт и сообщить, что именно не соответствует согласованному заданию. Такие обоснованные замечания мы исправляем без дополнительной оплаты. Просим описать расхождения с утверждённым заданием — это помогает отделить дефекты от новых пожеланий.","Jūs varēsiet pārbaudīt gatavo vietni un norādīt, kas tieši neatbilst saskaņotajam uzdevumam. Šādus pamatotus trūkumus novērsīsim bez papildu maksas. Lūdzam aprakstīt neatbilstības apstiprinātajam uzdevumam — tas palīdz atšķirt trūkumus no jaunām vēlmēm."],["Можно отказаться после старта?","Vai var atteikties pēc sākuma?","Возможен расчёт за фактически выполненную работу; детали по договору. Порядок расчёта зависит от того, какие работы уже выполнены и принят ли результат.","Iespējams norēķins par faktiski paveikto; detaļas pēc līguma. Norēķinu kārtība atkarīga no paveiktajiem darbiem un tā, vai rezultāts ir pieņemts."],["Вернёте деньги за незавершённое?","Vai atmaksāsiet par nepabeigto?","Переплата за невыполненные работы возвращается после расчёта. Мы покажем расчёт выполненных и невыполненных работ, чтобы возврат был понятным.","Pārmaksu par neizpildītiem darbiem atmaksā pēc aprēķina. Parādīsim paveikto un nepaveikto darbu aprēķinu, lai atmaksa būtu saprotama."],["Если уйду через три месяца?","Ja pārtraukšu pēc trim mēnešiem?","Зависит от готовности и приёмки сайта; дадим расчёт. При незавершённом проекте оплачивается надлежащим образом выполненная часть, а переплата возвращается.","Atkarīgs no vietnes pabeigšanas un pieņemšanas; sniegsim aprēķinu. Nepabeigtā projektā apmaksā pienācīgi paveikto daļu, bet pārmaksu atmaksā."],["Оплачивать оставшиеся месяцы?","Vai jāmaksā atlikušie mēneši?","Не обязательно все оставшиеся платежи. Если сайт уже завершён и принят, нужно будет погасить неоплаченную часть стоимости разработки, но не оплачивать поддержку, которая ещё не оказана. Точный расчёт покажем письменно. Это не штраф и не оплата будущих услуг, а расчёт за уже выполненную разработку.","Ne vienmēr jāveic visi atlikušie maksājumi. Ja vietne jau ir pabeigta un pieņemta, jāsamaksā neapmaksātā izstrādes daļa, bet ne par vēl nesniegtu atbalstu. Precīzu aprēķinu sniegsim rakstiski. Tas nav sods vai maksa par nākotnes pakalpojumiem, bet norēķins par jau paveikto izstrādi."],["Есть штраф за расторжение?","Vai ir sods par līguma izbeigšanu?","В проекте Start отдельного штрафа нет; расчёт за работу сохраняется. Чтобы избежать недоразумений, сумму и основания расчёта подтвердим письменно.","Start projektā atsevišķa soda nav; samaksa par paveikto saglabājas. Lai nerastos pārpratumi, summu un aprēķina pamatu apstiprināsim rakstiski."],["Если найдём ошибки?","Ja atklāsim kļūdas?","Наши ошибки и несоответствия заданию исправляем без доплаты. Сообщите, где возникает ошибка и как её воспроизвести, — так быстрее определим исправление.","Mūsu kļūdas un neatbilstības uzdevumam labojam bez piemaksas. Pastāstiet, kur rodas kļūda un kā to atkārtot, — tā ātrāk noteiksim labojumu."],["Кто отвечает за простой?","Kas atbild par dīkstāvi?","Причину и ответственность оцениваем по договору и закону; 24/7 не гарантируем. Сначала выясним, связана ли проблема с нашим кодом, хостингом или сторонним сервисом.","Cēloni un atbildību vērtē pēc līguma un likuma; 24/7 negarantējam. Vispirms noskaidrosim, vai problēma saistīta ar mūsu kodu, hostingu vai trešās puses pakalpojumu."],["Если сайт взломают?","Ja vietni uzlauzīs?","Рассмотрим инцидент; меры и ответственность зависят от обстоятельств. Важно сразу сохранить сведения об инциденте и ограничить дальнейший доступ злоумышленника.","Izskatīsim incidentu; rīcība un atbildība atkarīga no apstākļiem. Svarīgi nekavējoties saglabāt informāciju par incidentu un ierobežot turpmāku nesankcionētu piekļuvi."],["Гарантируете безопасность?","Vai garantējat drošību?","Абсолютной гарантии нет; меры защиты согласуем. Обсудим доступы, обновления и резервные копии; ни один сайт нельзя объявить полностью неуязвимым.","Absolūtas garantijas nav; aizsardzības pasākumus saskaņosim. Apspriedīsim piekļuves, atjauninājumus un rezerves kopijas; nevienu vietni nevar uzskatīt par pilnīgi neievainojamu."],["Как решаются споры?","Kā risina strīdus?","Сначала письменные переговоры, затем по праву Латвии. Поэтому существенные договорённости и замечания лучше сохранять в переписке.","Vispirms rakstiskas sarunas, pēc tam saskaņā ar Latvijas tiesībām. Tāpēc būtiskās vienošanās un piezīmes vēlams saglabāt sarakstē."],["Договор на компанию?","Vai līgumu var slēgt uzņēmums?","Да, договор рассчитан на сотрудничество с юридическим лицом. Для оформления понадобятся реквизиты компании, регистрационные данные и уполномоченный представитель, который вправе согласовать условия. Договор и счета оформляем на согласованную компанию, чтобы у бухгалтерии была полная документация.","Jā, līgums paredzēts sadarbībai ar juridisku personu. Sagatavošanai vajadzīgi uzņēmuma rekvizīti, reģistrācijas dati un pilnvarots pārstāvis, kuram ir tiesības saskaņot nosacījumus. Līgumu un rēķinus sagatavojam uz saskaņotā uzņēmuma vārda, lai grāmatvedībai būtu pilna dokumentācija."],["Можно как частное лицо?","Vai var kā privātpersona?","Нужна другая редакция договора; уточним возможность. Для физических лиц действуют иные требования, поэтому сначала уточним формат заказа.","Nepieciešama cita līguma redakcija; iespēju precizēsim. Privātpersonām ir citas prasības, tāpēc vispirms precizēsim pasūtījuma veidu."]]],["Права и уход","Tiesības un sadarbības beigas",[["Кому принадлежит сайт?","Kam pieder vietne?","После оплаты разработки — бессрочная неисключительная лицензия; общие модули остаются у Lomenti. Это позволяет вам использовать сайт для бизнеса, развивать его и менять подрядчика; исключительные авторские права автоматически не передаются.","Pēc izstrādes apmaksas — beztermiņa neekskluzīva licence; kopīgie moduļi paliek Lomenti. Tas ļauj izmantot vietni uzņēmējdarbībā, to attīstīt un mainīt izstrādātāju; ekskluzīvas autortiesības automātiski netiek nodotas."],["Когда получу права?","Kad iegūšu tiesības?","После полной оплаты согласованной разработки. До полной оплаты порядок использования определяется договором, поэтому важно завершить расчёт за разработку.","Pēc pilnas saskaņotās izstrādes apmaksas. Līdz pilnai apmaksai izmantošanas kārtību nosaka līgums, tādēļ svarīgi pabeigt norēķinu par izstrādi."],["Можно к другому разработчику?","Vai var pāriet pie cita izstrādātāja?","Да, цель сотрудничества — не привязать вас к одному исполнителю. После выполнения условий договора сайт и предусмотренные договором права и доступы передаются в согласованном порядке; использование сторонних компонентов зависит от их лицензий. Домен и хостинг оформляются на вас, поэтому при смене подрядчика не нужно терять адрес сайта.","Jā, sadarbības mērķis nav piesaistīt jūs vienam izpildītājam. Pēc līguma nosacījumu izpildes vietne un līgumā paredzētās tiesības un piekļuves tiek nodotas saskaņotajā kārtībā; trešo pušu komponentu izmantošanu nosaka licences. Domēns un hostings ir uz jūsu vārda, tāpēc, mainot izstrādātāju, nav jāzaudē vietnes adrese."],["Получим файлы?","Vai saņemsim failus?","При прекращении поддержки передаём доступные актуальные файлы и доступы. Передачу согласуем так, чтобы новый специалист мог разобраться в доступной структуре проекта.","Pārtraucot atbalstu, nododam pieejamos aktuālos failus un piekļuves. Nodošanu saskaņosim tā, lai jaunais speciālists varētu saprast pieejamo projekta struktūru."],["Домен на меня?","Vai domēns būs uz mana vārda?","Да. Домен лучше сразу зарегистрировать на вашу компанию или другого согласованного владельца, а не на разработчика. Тогда вы сможете самостоятельно продлевать его, менять регистратора и сохранять адрес даже при переходе к другому подрядчику. Оплата домена идёт отдельно от тарифа Start.","Jā. Domēnu iesakām uzreiz reģistrēt uz uzņēmuma vai cita saskaņota īpašnieka vārda, nevis uz izstrādātāju. Tad varēsiet paši to pagarināt, mainīt reģistratoru un paturēt adresi arī tad, ja mainīsiet pakalpojuma sniedzēju. Maksa par domēnu nav iekļauta Start tarifā."],["Чей хостинг?","Kam pieder hostinga konts?","Аккаунт и оплата принадлежат заказчику. Мы можем помочь с первоначальной настройкой, но доступ и отношения с провайдером остаются у вас.","Konts un maksājumi ir pasūtītāja ziņā. Varam palīdzēt ar sākotnējo iestatīšanu, bet piekļuve un attiecības ar pakalpojumu sniedzēju paliek jums."],["Можно уйти с поддержки?","Vai var atteikties no atbalsta?","После первого года — письменно предупредив минимум за 30 дней. Предупреждение направляется письменно, чтобы обе стороны знали дату окончания поддержки.","Pēc pirmā gada — rakstiski brīdinot vismaz 30 dienas iepriekš. Brīdinājumu nosūta rakstiski, lai abas puses zinātu atbalsta beigu datumu."],["Что после 12 месяцев?","Kas notiek pēc 12 mēnešiem?","Поддержка продолжается за 50 €/мес. до прекращения по договору. Если захотите прекратить сопровождение, соблюдаем предусмотренный договором порядок уведомления.","Atbalsts turpinās par 50 €/mēn. līdz izbeigšanai pēc līguma. Ja vēlaties izbeigt atbalstu, ievērojam līgumā paredzēto paziņošanas kārtību."],["Можно редактировать самому?","Vai var rediģēt pašam?","Право изменения после оплаты есть; панель редактирования согласуется отдельно. Если нужна самостоятельная панель управления, обсудим её ещё на этапе задания.","Tiesības mainīt pēc apmaksas ir; rediģēšanas paneli saskaņo atsevišķi. Ja vajadzīgs pašapkalpošanās rediģēšanas panelis, apspriedīsim to jau uzdevuma posmā."],["Другой разработчик может менять код?","Vai cits izstrādātājs var mainīt kodu?","Да, в рамках лицензии и сторонних ограничений. Новый специалист сможет продолжить работу, но ответственность за его изменения не переносится автоматически на нас.","Jā, licences un trešo pušu ierobežojumu ietvaros. Jaunais speciālists var turpināt darbu, bet atbildība par viņa izmaiņām automātiski nepāriet uz mums."],["Используете мой дизайн повторно?","Vai atkārtoti izmantosiet manu dizainu?","Конфиденциальные материалы и бренд не переносим; общие модули повторно используем. Ваши логотипы, тексты и закрытая информация не становятся шаблоном для других клиентов.","Konfidenciālus materiālus un zīmolu nepārnesam; kopīgus moduļus varam izmantot atkārtoti. Jūsu logotipi, teksti un slēgtā informācija nekļūst par veidni citiem klientiem."],["Можно запретить портфолио?","Vai var aizliegt publicēt portfolio?","Условия публикации согласуем отдельно; без разрешения не обещаем публикацию. Согласие на публикацию проекта и отзывов лучше оформлять отдельно.","Publicēšanas nosacījumus saskaņosim atsevišķi; bez atļaujas publicēšanu nesolām. Piekrišanu projekta un atsauksmju publicēšanai vēlams noformēt atsevišķi."],["Перенос платный?","Vai pārcelšana maksā?","Файлы и разумные инструкции — без доплаты; миграция и адаптация отдельно. Перенос может требовать работы с новым сервером и настройками — её стоимость согласуем до начала.","Faili un saprātīgas instrukcijas — bez piemaksas; migrācija un pielāgošana atsevišķi. Pārcelšanai var būt vajadzīgs darbs ar jaunu serveri un iestatījumiem — cenu saskaņosim pirms sākuma."],["Что будет с данными?","Kas notiks ar datiem?","Передачу и удаление согласуем по договору и DPA. Если сайт обрабатывает данные посетителей, порядок их обработки и удаления определим отдельно.","Nodošanu un dzēšanu saskaņosim pēc līguma un DPA. Ja vietne apstrādā apmeklētāju datus, to apstrādes un dzēšanas kārtību noteiksim atsevišķi."]]],["Поддержка","Atbalsts",[["Что входит в поддержку?","Kas ietilpst atbalstā?","2 небольшие правки контента в месяц, резервные копии и согласованное сопровождение. Новые разделы и сложные функции не входят автоматически в две небольшие правки.","2 nelieli satura labojumi mēnesī, rezerves kopijas un saskaņots atbalsts. Jaunas sadaļas un sarežģītas funkcijas automātiski neietilpst divos nelielajos labojumos."],["Что такое небольшая правка?","Kas ir neliels labojums?","Замена текста, фото или контактов без новых функций. Например, можно заменить номер телефона или короткое описание услуги без переделки дизайна.","Teksta, foto vai kontaktu maiņa bez jaunām funkcijām. Piemēram, var nomainīt tālruņa numuru vai īsu pakalpojuma aprakstu, nepārveidojot dizainu."],["Сколько правок в месяц?","Cik labojumu mēnesī?","В сопровождение включены две небольшие правки контента каждый месяц. Например, можно обновить короткий текст или заменить контактную информацию; полная смена дизайна, новый раздел или интеграция в этот объём не входят. Если понадобится больше изменений, сначала предложим дополнительную стоимость и начнём работу только после согласования.","Atbalstā ir iekļauti divi nelieli satura labojumi katru mēnesi. Piemēram, var atjaunot īsu tekstu vai kontaktinformāciju; pilnīga dizaina maiņa, jauna sadaļa vai integrācija šajā apjomā neietilpst. Ja vajadzēs vairāk, vispirms piedāvāsim papildu cenu un darbu sāksim tikai pēc saskaņošanas."],["Можно заменить фото и текст?","Vai var mainīt foto un tekstu?","Да, замена фотографии, контактного текста или короткого описания обычно относится к небольшой правке. В сопровождение входят две такие правки контента в месяц. Пришлите готовый материал и укажите страницу и место замены; если потребуется переделать целый раздел, заранее отдельно оценим объём.","Jā, foto, kontaktteksta vai īsa apraksta nomaiņa parasti ir neliels satura labojums. Atbalstā ietilpst divi šādi labojumi mēnesī. Atsūtiet gatavo materiālu un norādiet lapu un vietu; ja jāmaina vesela sadaļa, darba apjomu un cenu iepriekš saskaņosim atsevišķi."],["Можно изменить телефон и адрес?","Vai var mainīt telefonu un adresi?","Да, это типичный пример небольшой правки в поддержке. Вы присылаете актуальный номер или адрес и указываете, где он размещён — например, в шапке и на странице контактов. В тарифе предусмотрены две небольшие правки контента в месяц; если требуется более широкое обновление сайта, сначала согласуем объём.","Jā, tas ir tipisks neliels labojums atbalsta ietvaros. Atsūtiet aktuālo numuru vai adresi un norādiet, kur tas redzams, piemēram, galvenē un kontaktu lapā. Tarifā paredzēti divi nelieli satura labojumi mēnesī; plašākas izmaiņas vispirms saskaņojam atsevišķi."],["Если правок больше двух?","Ja vajag vairāk par diviem labojumiem?","Дополнительные работы оценим и согласуем письменно. Необязательно заказывать большой пакет: можем оценить только нужные вам изменения.","Papilddarbus novērtēsim un saskaņosim rakstiski. Nav obligāti jāpasūta liela pakete: varam novērtēt tikai nepieciešamās izmaiņas."],["Правки копятся?","Vai labojumi uzkrājas?","Нет, неиспользованные правки не переносятся. То есть два изменения предусмотрены в каждом месяце отдельно, а не суммируются за год.","Nē, neizmantotie labojumi nepārceļas. Tas nozīmē, ka katrā mēnesī paredzēti divi labojumi, nevis tie uzkrājas gada laikā."],["Как быстро отвечаете?","Cik ātri atbildat?","Стремимся ответить в течение 48 часов, без гарантии фиксированного срока. При обращении полезно сразу указать адрес сайта и суть вопроса, чтобы мы быстрее разобрались.","Cenšamies atbildēt 48 stundu laikā, negarantējot noteiktu termiņu. Vēršoties pie mums, norādiet vietnes adresi un problēmas būtību, lai ātrāk to izskatītu."],["Поддержка по выходным?","Vai atbalsts ir brīvdienās?","Сообщение можно отправить; круглосуточной поддержки нет. Если вопрос срочный, обозначьте это в сообщении, но не рассчитывайте на гарантированный ответ ночью.","Ziņu var nosūtīt; diennakts atbalsta nav. Ja jautājums ir steidzams, norādiet to ziņā, bet nepaļaujieties uz garantētu atbildi naktī."],["Если сайт упал?","Ja vietne nedarbojas?","Сообщите нам; серьёзные сбои приоритетны, срок восстановления не гарантируем. Укажите, когда заметили проблему и что именно не открывается; проверим причину и возможные действия.","Ziņojiet mums; nopietnas kļūmes ir prioritāras, atjaunošanas laiku negarantējam. Norādiet, kad pamanījāt problēmu un kas tieši neatveras; pārbaudīsim cēloni un iespējamo rīcību."],["Делаете копии?","Vai veidojat rezerves kopijas?","Для Start — не реже раза в 7 дней, храним минимум 4 последние отдельно при технической возможности. Резервные копии помогают восстановлению, но не заменяют отдельную проверку работоспособности сайта.","Start — vismaz reizi 7 dienās, glabājam vismaz 4 pēdējās atsevišķi, ja tehniski iespējams. Rezerves kopijas palīdz atjaunošanā, bet neaizstāj atsevišķu vietnes darbības pārbaudi."],["Можно восстановить?","Vai var atjaunot vietni?","Проверяем пригодность копий, но отсутствие потерь не гарантируем. Восстановление зависит от наличия исправной копии и от того, что произошло после её создания.","Pārbaudām kopiju derīgumu, bet datu zuduma neesamību negarantējam. Atjaunošana atkarīga no derīgas kopijas un izmaiņām pēc tās izveides."],["Технические обновления?","Vai veicat tehniskus atjauninājumus?","Объём определён приложением; дополнительные работы отдельно. Например, обновления сторонних платформ и плагинов могут требовать отдельной оценки совместимости.","Apjoms noteikts pielikumā; papilddarbi atsevišķi. Piemēram, trešo pušu platformu un spraudņu atjauninājumiem var būt vajadzīgs savietojamības izvērtējums."],["Исправление ошибок платное?","Vai kļūdu labošana maksā?","Наши ошибки в согласованном задании исправляем бесплатно. Важно различать ошибку в согласованной работе и просьбу добавить новую возможность.","Mūsu kļūdas saskaņotajā uzdevumā labojam bez maksas. Svarīgi atšķirt kļūdu saskaņotajā darbā no lūguma pievienot jaunu funkciju."],["Можно поставить поддержку на паузу?","Vai var apturēt atbalstu uz laiku?","Автоматического права нет, обсудим индивидуально. Если поддержка временно не нужна, напишите нам — проверим, какой вариант допускают условия договора.","Automātisku tiesību nav, apspriedīsim individuāli. Ja atbalsts uz laiku nav vajadzīgs, uzrakstiet mums — pārbaudīsim, ko pieļauj līgums."]]],["Магазины и доработки","Veikali un pielāgojumi",[["Создаёте магазины?","Vai veidojat e-veikalus?","Да, интернет-магазины можно обсудить как отдельные проекты, но их стоимость нельзя приравнивать к Start за 50 € в месяц. Нам нужно понять, сколько товаров и вариантов, требуется ли онлайн-оплата, доставка и управление заказами. После этого выберем подходящую архитектуру и согласуем стоимость до начала разработки.","Jā, interneta veikalus varam apspriest kā atsevišķus projektus, taču to cenu nevar pielīdzināt Start 50 € mēnesī. Jāsaprot preču un variantu skaits, tiešsaistes apmaksa, piegāde un pasūtījumu pārvaldība. Pēc tam izvēlēsimies piemērotu risinājumu un cenu saskaņosim pirms izstrādes."],["Цена магазина?","Cik maksā e-veikals?","Для интернет-магазина нет общей цены Start в 50 € в месяц: он оценивается как отдельный проект. Например, каталог из 20 товаров без оплаты и магазин с 200 товарами, размерами, корзиной, доставкой и банковскими платежами — разные объёмы работы. Уточним ассортимент, функции и платформу, после чего подготовим смету до начала разработки.","Interneta veikalam nav vienotas Start cenas 50 € mēnesī: to vērtē kā atsevišķu projektu. Piemēram, katalogs ar 20 precēm bez maksājumiem un veikals ar 200 precēm, izmēriem, grozu, piegādi un bankas maksājumiem ir ļoti atšķirīgi darba apjomi. Precizēsim sortimentu, funkcijas un platformu, pēc tam sagatavosim tāmi pirms izstrādes."],["Можно оплату картой?","Vai var pievienot karšu maksājumus?","Да, при согласовании сервиса и интеграции. Платёжный провайдер может взимать собственные комиссии, которые не входят в разработку.","Jā, saskaņojot pakalpojumu un integrāciju. Maksājumu pakalpojumu sniedzējs var piemērot savas komisijas, kas nav iekļautas izstrādē."],["Работаете с Shopify?","Vai strādājat ar Shopify?","Проверим выбранную платформу и возможность реализации. У платформы могут быть отдельные тарифы и ограничения, поэтому уточним ваш текущий тариф и задачу.","Pārbaudīsim izvēlēto platformu un īstenošanas iespēju. Platformai var būt atsevišķi tarifi un ierobežojumi, tādēļ precizēsim jūsu plānu un vajadzību."],["Можно Omniva или DPD?","Vai var pievienot Omniva vai DPD?","Такую доставку можно рассмотреть, если платформа магазина и условия перевозчика позволяют интеграцию. Уточним, нужно ли выбирать пакомат, рассчитывать стоимость доставки и автоматически передавать данные заказа. После проверки доступных модулей или API сможем оценить стоимость подключения; Start эту работу не включает.","Šādu piegādi var apsvērt, ja veikala platforma un pārvadātāja nosacījumi atļauj integrāciju. Precizēsim, vai jāizvēlas pakomāts, jāaprēķina piegādes cena un automātiski jānodod pasūtījuma dati. Pēc pieejamo moduļu vai API pārbaudes varēsim novērtēt pieslēgšanas cenu; Start šo darbu neietver."],["Можно импортировать товары?","Vai var importēt preces?","Оценим по объёму и формату исходных данных. Лучше заранее проверить пример файла, чтобы избежать потери описаний, цен и изображений.","Izvērtēsim pēc apjoma un datu formāta. Labāk iepriekš pārbaudīt faila paraugu, lai nezaudētu aprakstus, cenas un attēlus."],["Сколько товаров?","Cik daudz preču?","Фиксированного числа товаров для индивидуального магазина заранее не обещаем. Важно понимать не только количество карточек, но и варианты — размеры, цвета, остатки, категории — и как часто ассортимент обновляется. По этим данным оценим структуру каталога, импорт и сопровождение, затем согласуем объём и цену.","Individuālam veikalam iepriekš nesolām fiksētu preču skaitu. Svarīgs ir ne tikai preču kartīšu daudzums, bet arī varianti — izmēri, krāsas, atlikumi, kategorijas — un sortimenta atjaunošanas biežums. Pēc šiem datiem izvērtēsim kataloga struktūru, importu un atbalstu, tad saskaņosim apjomu un cenu."],["Складской учёт?","Vai var integrēt noliktavas uzskaiti?","Возможность зависит от платформы магазина и учётной системы, которую вы уже используете. Сначала уточним, нужно ли синхронизировать остатки, цены, артикулы или заказы, и как часто данные должны обновляться. Только после проверки совместимости назовём объём и стоимость интеграции.","Tas ir atkarīgs no veikala platformas un jūsu uzskaites sistēmas. Vispirms precizēsim, vai jāsaskaņo atlikumi, cenas, preču kodi vai pasūtījumi un cik bieži dati jāatjaunina. Tikai pēc savietojamības pārbaudes noteiksim integrācijas apjomu un cenu."],["Кто отвечает за возвраты?","Kas atbild par preču atgriešanu?","Владелец магазина отвечает за продажи, цены, доставку и возвраты. Мы разрабатываем техническую часть, а коммерческие правила магазина определяет его владелец.","Veikala īpašnieks atbild par pārdošanu, cenām, piegādi un atgriešanu. Mēs izstrādājam tehnisko daļu, bet veikala komercnoteikumus nosaka tā īpašnieks."],["Платёжные сервисы отдельно?","Vai maksājumu servisi maksā atsevišķi?","Да. Подключение платежей и комиссии самого платёжного провайдера — разные статьи расходов. Сначала уточним, нужны ли оплата картой, банковские переводы или другие способы, затем проверим совместимость платформы и условия провайдера. До запуска покажем, какие затраты относятся к нашей работе, а какие оплачиваются стороннему сервису.","Jā. Maksājumu pieslēgšana un paša maksājumu pakalpojuma sniedzēja komisijas ir dažādas izmaksas. Vispirms precizēsim kartes maksājumus, bankas pārskaitījumus vai citus veidus, tad pārbaudīsim platformas savietojamību un sniedzēja nosacījumus. Pirms palaišanas parādīsim, kas attiecas uz mūsu darbu un kas jāmaksā trešajai pusei."],["Можно улучшить готовый магазин?","Vai var uzlabot esošu veikalu?","Возможно. Сначала посмотрим платформу магазина и конкретную проблему: медленная мобильная версия, сложная корзина, неудобная карточка товара или интеграция доставки. Не обязательно переписывать магазин полностью, если вопрос решается одной доработкой. Объём и стоимость согласуем после технической проверки.","Iespējams. Vispirms apskatīsim veikala platformu un konkrēto problēmu: lēna mobilā versija, sarežģīts grozs, neērta preces lapa vai piegādes integrācija. Nav jāpārveido viss veikals, ja problēmu var atrisināt ar vienu uzlabojumu. Darba apjomu un cenu saskaņosim pēc tehniskās pārbaudes."],["Как платят за индивидуальный проект?","Kā apmaksā individuālu projektu?","Стандартно 50% / 30% / 20% по этапам, если не согласовано иначе. Этапы, результаты и даты платежей укажем в индивидуальном договоре.","Parasti 50% / 30% / 20% pa posmiem, ja nav saskaņots citādi. Posmus, rezultātus un maksājumu datumus norādīsim individuālajā līgumā."],["Поддержка магазина включена?","Vai veikala atbalsts iekļauts?","Нет, сопровождение интернет-магазина не входит автоматически в информационный Start. В магазине могут быть отдельные задачи — обновление товаров, исправления корзины, платёжные системы, доставка и безопасность. Сначала уточним, кто за что отвечает, какой объём поддержки нужен, и закрепим цену отдельно.","Nē, interneta veikala uzturēšana nav automātiski iekļauta informatīvajā Start. Veikalā var būt atsevišķi darbi — preču atjaunošana, groza labojumi, maksājumu sistēmas, piegāde un drošība. Vispirms precizēsim atbildību un vajadzīgo atbalsta apjomu, pēc tam cenu saskaņosim atsevišķi."]]],["AI-чат-бот","AI čatbots",[["Что умеет AI-бот?","Ko prot AI čatbots?","Отвечает на информационные вопросы по согласованным источникам. Например, может объяснять услуги, режим работы и порядок обращения, если эти сведения предоставлены.","Atbild uz informatīviem jautājumiem no saskaņotiem avotiem. Piemēram, var izskaidrot pakalpojumus, darba laiku un saziņas kārtību, ja šī informācija ir pieejama."],["Чем отличается от обычного чата?","Ar ko atšķiras no parasta čata?","Понимает свободные вопросы, а не только кнопки. Но даже AI-боту нужны проверенные данные и правила, когда лучше передать вопрос сотруднику.","Saprot brīvi formulētus jautājumus, ne tikai pogas. Taču arī AI botam vajadzīgi pārbaudīti dati un noteikumi, kad jautājumu nodot darbiniekam."],["Сколько стоит AI-бот?","Cik maksā AI čatbots?","Здесь стоимость зависит от того, на какие вопросы бот должен отвечать и какие функции выполнять. Мы сначала уточним ваши задачи, а затем предложим подходящее решение и цену. После обсуждения подготовим перечень функций, источников данных и ожидаемых расходов.","Cena ir atkarīga no tā, uz kādiem jautājumiem botam jāatbild un kādas funkcijas tam jāpilda. Vispirms precizēsim jūsu vajadzības, pēc tam piedāvāsim risinājumu un cenu. Pēc sarunas sagatavosim funkciju, datu avotu un paredzamo izmaksu sarakstu."],["Есть абонентская плата?","Vai ir abonēšanas maksa?","Поддержка, API и сервисы рассчитываются отдельно. Отдельно уточним плату за использование модели, объём обращений и техническое сопровождение.","Atbalstu, API un pakalpojumus aprēķina atsevišķi. Atsevišķi precizēsim modeļa izmantošanas maksu, pieprasījumu apjomu un tehnisko atbalstu."],["Отвечает на RU и LV?","Vai atbild RU un LV?","Можно настроить оба языка и проверить тестами. Проверим типичные вопросы на обоих языках до запуска, чтобы избежать неверных формулировок.","Var iestatīt abas valodas un pārbaudīt testos. Pirms palaišanas pārbaudīsim tipiskus jautājumus abās valodās, lai izvairītos no kļūdainiem formulējumiem."],["Работает круглосуточно?","Vai darbojas visu diennakti?","Может быть доступен постоянно, но 24/7 не гарантируем. Доступность зависит также от сайта, интернета и внешних сервисов, поэтому абсолютной гарантии нет.","Var būt pieejams nepārtraukti, bet 24/7 negarantējam. Pieejamība ir atkarīga arī no vietnes, interneta un ārējiem pakalpojumiem, tādēļ absolūtas garantijas nav."],["Может принимать заявки?","Vai var saņemt pieteikumus?","Можно настроить передачу на email или CRM с защитой данных. До запуска согласуем, какие поля собирать, кому передавать заявку и как защищать данные.","Var iestatīt nodošanu uz e-pastu vai CRM ar datu aizsardzību. Pirms palaišanas saskaņosim, kādus laukus vākt, kam nodot pieteikumu un kā aizsargāt datus."],["Передаёт человеку?","Vai nodod jautājumu cilvēkam?","Такой сценарий можно предусмотреть: когда вопрос выходит за рамки знаний бота, он предлагает оставить заявку или связаться с сотрудником по согласованному каналу. Это не означает, что человек отвечает круглосуточно — график и способ связи определяются отдельно. До запуска согласуем, какие вопросы бот должен передавать дальше.","Šādu scenāriju var paredzēt: ja jautājums pārsniedz bota zināšanas, tas piedāvā atstāt pieteikumu vai sazināties ar darbinieku saskaņotajā kanālā. Tas nenozīmē, ka cilvēks atbild visu diennakti — darba laiku un saziņas veidu saskaņo atsevišķi. Pirms palaišanas vienosimies, kurus jautājumus bots nodod tālāk."],["Подключите к готовому сайту?","Vai pieslēgsiet esošai vietnei?","Возможно, но сначала нужно проверить, на какой платформе работает сайт и разрешает ли она встроить виджет или подключить нужные функции. Например, статический сайт и магазин на готовой платформе могут иметь разные ограничения. После технической проверки скажем, что можно сделать и во сколько обойдётся интеграция; в Start она автоматически не входит.","Iespējams, taču vispirms jāpārbauda, uz kādas platformas darbojas vietne un vai tajā drīkst ievietot logrīku vai vajadzīgās funkcijas. Piemēram, statiskai vietnei un gatavas platformas veikalam var būt atšķirīgi ierobežojumi. Pēc tehniskās pārbaudes pateiksim, kas iespējams un cik maksās integrācija; tā nav automātiski iekļauta Start."],["Откуда берёт информацию?","No kurienes ņem informāciju?","Бот отвечает на основе согласованных материалов: описаний услуг, FAQ, контактов, правил и других предоставленных источников. Например, если цена изменилась с 30 € на 35 €, информацию нужно обновить, иначе бот может назвать старую цену. Перед запуском договоримся, кто сообщает об изменениях и как проверяются ответы.","Bots atbild, izmantojot saskaņotus materiālus: pakalpojumu aprakstus, BUJ, kontaktus, noteikumus un citus dotus avotus. Piemēram, ja cena mainās no 30 € uz 35 €, informācija jāatjauno, citādi bots var nosaukt veco cenu. Pirms palaišanas vienosimies, kurš ziņo par izmaiņām un kā pārbauda atbildes."],["Может ошибаться?","Vai var kļūdīties?","Да; поэтому нужны тесты и передача сложных вопросов человеку. Поэтому для важных решений не стоит полагаться только на ответ бота без проверки человеком.","Jā; tāpēc vajadzīgi testi un sarežģītu jautājumu nodošana cilvēkam. Tādēļ svarīgus lēmumus nevajadzētu balstīt tikai uz bota atbildi bez cilvēka pārbaudes."],["Если ответит неправильно?","Ja atbildēs nepareizi?","Риски и ответственность рассматриваются по условиям и обстоятельствам. Ошибку разберём, проверим источник информации и при необходимости изменим настройки.","Riskus un atbildību vērtē pēc nosacījumiem un apstākļiem. Kļūdu izskatīsim, pārbaudīsim informācijas avotu un vajadzības gadījumā mainīsim iestatījumus."],["Может оформлять заказы?","Vai var noformēt pasūtījumus?","Наш информационный бот не заключает сделки и не принимает деньги. Если нужна полноценная автоматизация заказов, это уже отдельный проект с другими требованиями.","Mūsu informatīvais bots neslēdz darījumus un nepieņem naudu. Ja vajadzīga pilna pasūtījumu automatizācija, tas ir atsevišķs projekts ar citām prasībām."],["Кто видит переписки?","Kas redz sarakstes?","Зависит от архитектуры; постоянный архив у Lomenti по умолчанию не создаётся. Перед запуском согласуем доступ сотрудников, журналирование и правила хранения сообщений.","Atkarīgs no arhitektūras; Lomenti pēc noklusējuma neveido pastāvīgu arhīvu. Pirms palaišanas saskaņosim darbinieku piekļuvi, žurnalēšanu un ziņu glabāšanas noteikumus."],["Где хранятся данные?","Kur glabājas dati?","Провайдеры и сроки фиксируются до запуска в DPA. Без конкретной архитектуры нельзя обещать определённую страну хранения или срок удаления.","Pakalpojumu sniedzējus un termiņus fiksē DPA pirms palaišanas. Bez konkrētas arhitektūras nevar solīt noteiktu glabāšanas valsti vai dzēšanas termiņu."],["Соответствует GDPR?","Vai atbilst GDPR?","Конфигурацию и DPA проверяем до запуска; без проверки гарантий нет. Проверим, какие персональные данные обрабатываются, кто является обработчиком и какие документы нужны.","Konfigurāciju un DPA pārbaudām pirms palaišanas; bez pārbaudes garantiju nav. Pārbaudīsim, kādi personas dati tiek apstrādāti, kurš ir apstrādātājs un kādi dokumenti vajadzīgi."],["Можно протестировать?","Vai var izmēģināt?","Демонстрацию обсудим; тестирование перед приёмкой предусмотрено. В тестах полезно проверить сложные вопросы, ошибки, переключение языка и передачу оператору.","Demonstrāciju apspriedīsim; testēšana pirms pieņemšanas paredzēta. Testos noder pārbaudīt sarežģītus jautājumus, kļūdas, valodu maiņu un nodošanu operatoram."],["Как обновлять информацию?","Kā atjaunot informāciju?","Изменения в ценах, услугах, графике и правилах должны попадать не только на сайт, но и в базу знаний бота. Согласуем, кто присылает новые данные, как их подтверждают и кто проверяет обновлённый ответ. Регулярность и стоимость таких обновлений зависят от договора поддержки бота; в Start сайта они автоматически не входят.","Izmaiņas cenās, pakalpojumos, darba laikā un noteikumos jāievieš ne tikai vietnē, bet arī bota zināšanu bāzē. Vienosimies, kurš nosūta jaunos datus, kā tos apstiprina un kurš pārbauda atjaunoto atbildi. Šo atjauninājumu biežums un cena atkarīga no bota atbalsta līguma; tie nav automātiski iekļauti mājaslapas Start."]]],["О Lomenti","Par Lomenti",[["Как давно работаете?","Cik ilgi strādājat?","Развиваем Lomenti; точную дату деятельности уточним. Вместо неподтверждённых дат лучше покажем, какие решения уже можем продемонстрировать.","Attīstām Lomenti; precīzu darbības sākumu precizēsim. Nepārbaudītu datumu vietā labāk parādīsim risinājumus, ko jau varam demonstrēt."],["Сколько сайтов сделали?","Cik vietņu esat izveidojuši?","Покажем подтверждённые проекты и концепты, не смешивая их. Если вас интересует конкретная задача, подберём наиболее близкий по функциональности пример.","Parādīsim apstiprinātus projektus un konceptus, tos nejaucot. Ja interesē konkrēts uzdevums, piemeklēsim pēc funkcijām tuvāko piemēru."],["Есть реальные клиенты?","Vai ir īsti klienti?","Предоставим только разрешённые к показу сведения. Мы не будем представлять демонстрационные концепты как оплаченные клиентские проекты.","Sniegsim tikai informāciju, ko drīkst publiskot. Demonstrācijas konceptus neuzdosim par apmaksātiem klientu projektiem."],["Есть отзывы?","Vai ir atsauksmes?","Направим доступные опубликованные отзывы, если они есть. Если публичных отзывов пока нет, так и скажем и предложим посмотреть демонстрацию.","Nosūtīsim pieejamās publicētās atsauksmes, ja tādas ir. Ja publisku atsauksmju vēl nav, to pateiksim un piedāvāsim apskatīt demonstrāciju."],["Почему так дёшево?","Kāpēc tik lēti?","Start ограничен понятным объёмом, без ненужных функций. Стоимость ниже за счёт чётких границ Start: до пяти страниц и без сложных интеграций.","Start ir skaidri ierobežots apjoms bez liekām funkcijām. Cena ir zemāka skaidra Start apjoma dēļ: līdz piecām lapām un bez sarežģītām integrācijām."],["Если Lomenti закроется?","Ja Lomenti pārtrauks darbību?","Домен и хостинг ваши, права и файлы передаются по договору. Это снижает зависимость от одного исполнителя и помогает продолжить работу с другим специалистом.","Domēns un hostings pieder jums; tiesības un failus nodod pēc līguma. Tas mazina atkarību no viena izstrādātāja un palīdz turpināt darbu ar citu speciālistu."],["Кто мой контакт?","Kas būs mana kontaktpersona?","После согласования сотрудничества закрепим ответственного человека и основной письменный канал связи. Так запросы по текстам, фотографиям и поддержке не потеряются среди разных переписок. В договоре или рабочих документах укажем, кому отправлять материалы и кто подтверждает изменения.","Pēc sadarbības saskaņošanas norādīsim atbildīgo personu un galveno rakstiskās saziņas kanālu. Tad pieprasījumi par tekstiem, foto un atbalstu nepazudīs dažādās sarakstēs. Līgumā vai darba dokumentos norādīsim, kam sūtīt materiālus un kurš apstiprina izmaiņas."],["Можно поговорить с разработчиком?","Vai var runāt ar izstrādātāju?","Если вопрос технический, передадим его разработчику и согласуем удобный способ ответа. Например, можно заранее прислать ссылку на сайт и описать проблему с формой, мобильной версией или интеграцией. Так специалист сможет подготовить предметный ответ без лишних созвонов.","Ja jautājums ir tehnisks, nodosim to izstrādātājam un saskaņosim piemērotu atbildes veidu. Piemēram, var iepriekš atsūtīt vietnes saiti un aprakstīt problēmu ar formu, mobilo versiju vai integrāciju. Tad speciālists varēs sagatavot konkrētu atbildi bez liekiem zvaniem."],["Есть опыт в моей отрасли?","Vai ir pieredze manā nozarē?","Покажем только подтверждённые подходящие примеры. Если прямого примера в вашей отрасли нет, покажем похожие задачи, не выдавая их за отраслевой опыт.","Parādīsim tikai apstiprinātus atbilstošus piemērus. Ja nav tieša piemēra jūsu nozarē, parādīsim līdzīgus uzdevumus, neuzdodot tos par nozares pieredzi."],["Почему выбрать вас?","Kāpēc izvēlēties jūs?","Понятный тариф, письменные условия, согласование задач и поддержка. Предлагаем начать с ваших задач и согласовать только те функции, которые действительно нужны.","Skaidrs tarifs, rakstiski nosacījumi, uzdevumu saskaņošana un atbalsts. Piedāvājam sākt ar jūsu vajadzībām un saskaņot tikai patiešām nepieciešamās funkcijas."]]],["Начало сотрудничества","Sadarbības sākums",[["Что дальше, если согласен?","Kas tālāk, ja piekrītu?","Уточним задачи и контакт, затем подготовим предложение. Уточним, какие услуги вы предлагаете, есть ли сайт сейчас и какой результат для вас важен.","Precizēsim vajadzības un kontaktu, tad sagatavosim piedāvājumu. Precizēsim jūsu pakalpojumus, vai vietne jau ir un kāds rezultāts jums svarīgs."],["Обязательна встреча?","Vai obligāti jātiekas?","Нет, при достаточной информации можно всё согласовать письменно. Созвон или встречу предложим только если это действительно поможет решить сложный вопрос.","Nē, ja informācijas pietiek, visu var saskaņot rakstiski. Zvanu vai tikšanos piedāvāsim tikai tad, ja tas tiešām palīdzēs atrisināt sarežģītu jautājumu."],["Можно всё по email?","Vai visu var e-pastā?","Да, конечно. Мы можем обсудить задачи, согласовать предложение и оформить необходимые документы по электронной почте. В переписке удобно сохранить согласованные требования, цены и сроки.","Jā. Varam pārrunāt vajadzības, saskaņot piedāvājumu un nokārtot dokumentus e-pastā. Sarakstē ērti saglabāt saskaņotās prasības, cenas un termiņus."],["Сначала покажете дизайн?","Vai vispirms parādīsiet dizainu?","Формат предварительной демонстрации обсудим; бесплатный дизайн не обещаем. После согласования задания подготовим первый вариант в предусмотренном проектом порядке.","Iepriekšējas demonstrācijas formu apspriedīsim; bezmaksas dizainu nesolām. Pēc uzdevuma saskaņošanas sagatavosim pirmo variantu projektā paredzētajā kārtībā."],["Можно индивидуальное предложение?","Vai var individuālu piedāvājumu?","Да. Сначала уточним, сколько нужно страниц, на каких языках, нужна ли форма заявки, каталог, запись или другие функции. Если хватает информационного сайта до 5 страниц, предложим Start за 50 € в месяц с НДС; нестандартный проект оценим отдельно. Так вы получите предложение по своей задаче, а не общий прайс без деталей.","Jā. Vispirms precizēsim lapu skaitu, vajadzīgās valodas, pieteikuma formu, katalogu, pierakstu un citas funkcijas. Ja pietiek ar informatīvu vietni līdz 5 lapām, piedāvāsim Start par 50 € mēnesī ar PVN; nestandarta projektu novērtēsim atsevišķi. Tā saņemsiet piedāvājumu savai vajadzībai, nevis vispārīgu cenu lapu."],["Какие материалы нужны?","Kādi materiāli vajadzīgi?","Информация о компании, услуги, контакты, фото, тексты и пожелания. Если материалов много, можно начать с основных и составить список недостающего.","Uzņēmuma informācija, pakalpojumi, kontakti, foto, teksti un vēlmes. Ja materiālu ir daudz, var sākt ar galveno un izveidot trūkstošā sarakstu."],["Когда договор и счёт?","Kad būs līgums un rēķins?","После того как согласуем список страниц, функции, цену и порядок работы, отправим договор на ознакомление. Первый счёт выставляем после согласования условий; для Start первый платёж составляет 50 € и входит в общую стоимость первого года 600 €. До оплаты вы сможете задать вопросы по договору и уточнить непонятные пункты.","Pēc lapu saraksta, funkciju, cenas un darba kārtības saskaņošanas nosūtīsim līgumu iepazīšanai. Pirmo rēķinu izrakstīsim pēc nosacījumu apstiprināšanas; Start pirmais maksājums ir 50 € un ietilpst pirmā gada kopējā 600 € summā. Pirms apmaksas varēsiet uzdot jautājumus par līgumu."],["Можно начать с малого?","Vai var sākt ar nelielu projektu?","Да, это разумный вариант для бизнеса, которому пока нужен только понятный сайт с услугами и контактами. Start предусматривает до 5 информационных страниц, мобильную адаптацию и согласованные формы. Если позже появится задача добавить каталог, запись или новые страницы, заранее оценим их как отдельное расширение.","Jā, tas ir saprātīgs variants uzņēmumam, kam pagaidām vajag skaidru vietni ar pakalpojumiem un kontaktiem. Start paredz līdz 5 informatīvām lapām, pielāgošanu mobilajām ierīcēm un saskaņotas formas. Ja vēlāk vajadzēs katalogu, pierakstu vai jaunas lapas, tos iepriekš novērtēsim kā atsevišķu paplašinājumu."],["Кто согласует изменения?","Kas saskaņo izmaiņas?","Назначенные контактные лица, письменно. Лучше назначить одного ответственного с вашей стороны, чтобы не получать противоречивые замечания.","Norādītās kontaktpersonas, rakstiski. Labāk nozīmēt vienu atbildīgo no jūsu puses, lai nesaņemtu pretrunīgas piezīmes."],["Как передаётся сайт?","Kā nodod vietni?","Проверка, акт или email-подтверждение, файлы и доступы по договору. Перед передачей проверим согласованные функции и зафиксируем замечания или подтверждение приёмки.","Pārbaude, akts vai e-pasta apstiprinājums, faili un piekļuves pēc līguma. Pirms nodošanas pārbaudīsim saskaņotās funkcijas un fiksēsim piezīmes vai pieņemšanas apstiprinājumu."]]]];
let faqCategory=-1;
function renderFaq(){
 const app=document.getElementById('app');app.replaceChildren();
 const ru=language==='ru';const back=document.createElement('button');back.className='back';back.textContent=ru?'← К сценариям':'← Pie scenārijiem';back.onclick=()=>{window.faqOpen=false;scenario=null;path=[];render()};app.append(back);
 const h=document.createElement('h1');h.textContent=ru?'Вопросы клиентов':'Klientu jautājumi';app.append(h);
 const info=document.createElement('p');info.className='intro';info.textContent=ru?'Ответы по проекту договора от 03.11.2026. Условия, отмеченные для согласования, уточняйте у команды.':'Atbildes pēc 03.11.2026. līguma projekta. Nesaskaņotos nosacījumus precizējiet komandā.';app.append(info);
 const categories=document.createElement('div');categories.className='faq-cats';app.append(categories);
 const list=document.createElement('div');list.className='faq-results';app.append(list);
 function update(){categories.replaceChildren();const all=document.createElement('button');all.className='choice'+(faqCategory===-1?' active':'');all.textContent=ru?'Все темы':'Visas tēmas';all.onclick=()=>{faqCategory=-1;update()};categories.append(all);
 FAQ_GROUPS.forEach((g,i)=>{const b=document.createElement('button');b.className='choice'+(faqCategory===i?' active':'');b.textContent=g[ru?0:1];b.onclick=()=>{faqCategory=faqCategory===i?-1:i;update()};categories.append(b)});
 list.replaceChildren();let shown=0;
 FAQ_GROUPS.forEach((g,i)=>{if(faqCategory!==-1&&faqCategory!==i)return;const matched=g[2];if(!matched.length)return;const title=document.createElement('h2');title.className='faq-heading';title.textContent=g[ru?0:1]+' · '+matched.length;list.append(title);matched.forEach(row=>{shown++;const item=document.createElement('details');item.className='faq-item';const summary=document.createElement('summary');summary.textContent=row[ru?0:1];const answer=document.createElement('p');answer.textContent=row[ru?2:3];item.append(summary,answer);list.append(item)})});if(!shown){const empty=document.createElement('p');empty.className='intro';empty.textContent=ru?'Ничего не найдено':'Nekas nav atrasts';list.append(empty)}
 }
 update();
}
